sp_AtualizarCabecalhoPedido	ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION	CREATE DEFINER=`root`@`%` PROCEDURE `sp_AtualizarCabecalhoPedido`(\n\n    p_idPedido INT,\n\n    p_valorTotal DECIMAL(10,2),\n\n    p_Desconto DECIMAL(10,2),\n\n    p_valorFrete DECIMAL(10,2),\n\n    p_Observacao VARCHAR(500)\n\n)\nBEGIN\n\n    UPDATE Pedido\n\n    SET valorTotal = p_valorTotal,\n\n        Desconto   = p_Desconto,\n\n        valorFrete = p_valorFrete,\n\n        Observacao = p_Observacao\n\n    WHERE idPedido = p_idPedido;\n\nEND	utf8mb4	utf8mb4_0900_ai_ci	utf8mb4_0900_ai_ci
